// spec: specs/contact-login-return.md (4.5) · кейс: .qa/tests/contact-login-return/CONTACT-AUTH-16.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. На /auth НЕ нажимать «שלח קוד», «התחבר», «שלח קישור», Google —
// только переключение экранов внутри /auth.
import { test, expect, Page } from '@playwright/test';
import { prepareGuest, openAuthFromPopup, expectReturnToListing, INTENT_BIZ } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

async function expectStillKept(page: Page, step: string, withIntent = true) {
  expect(new URL(page.url()).pathname, `${step}: остались на /auth`).toBe('/auth');
  if (withIntent) await expect(page.getByText(INTENT_BIZ).first(), `${step}: текст «${INTENT_BIZ}» на месте`).toBeVisible();
  await expectReturnToListing(page, step);
}

test.describe('Отказ от входа — адрес возврата и намерение очищаются', () => {
  test('Переходы внутри /auth (почта, вкладки, «שכחתי סיסמה», снова SMS) не стирают возврат и намерение #a88c1c @android @prod-safe', async ({ page }) => {
    await prepareGuest(page);
    await openAuthFromPopup(page);

    await page.getByText('כניסה עם אימייל וסיסמה').first().click();
    await expect(page.getByText('שכחתי סיסמה').first()).toBeVisible();
    await expectStillKept(page, 'вход по почте');

    await page.getByText('הרשמה', { exact: true }).first().click();
    await expect(page.getByText('אני מאשר/ת את תנאי השימוש', { exact: false }).first()).toBeVisible();
    await expectStillKept(page, 'вкладка «הרשמה»');

    await page.getByText('התחברות', { exact: true }).first().click();
    await expect(page.getByText('שכחתי סיסמה').first()).toBeVisible();
    await expectStillKept(page, 'вкладка «התחברות»');

    await page.getByText('שכחתי סיסמה').first().click();
    await expect(page.getByText('איפוס סיסמה').first()).toBeVisible();
    await expectStillKept(page, 'экран «איפוס סיסמה»', false);

    await page.getByText('חזרה', { exact: true }).first().click();
    await expect(page.getByText('התחברות מהירה עם SMS').first()).toBeVisible();
    await expectStillKept(page, '«חזרה» с экрана сброса');

    await page.getByText('התחברות מהירה עם SMS').first().click();
    await expect(page.getByText('שלח קוד').first()).toBeVisible();
    await expectStillKept(page, 'снова экран SMS');
  });
});
